#include <iostream>
#include <vector>
#include <string>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    long long L;
    cin >> n >> m >> L;
    vector<vector<long long>> roads(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> roads[i][j];
        }
    }

    const long long MOD = 1000000007;
    int size = 3 * (int)n;
    vector<vector<long long>> mat(size, vector<long long>(size, 0));
    for (int v = 0; v < n; v++) {
        mat[3 * v + 1][3 * v] += 1;
        mat[3 * v + 2][3 * v + 1] += 1;
    }
    for (long long k = 0; k < m; k++) mat[3 * (roads[k][0] - 1)][3 * (roads[k][1] - 1) + roads[k][2] - 1] += 1;
    vector<long long> vec(size, 0);
    vec[0] = 1;
    while (L > 0) {
        if (L & 1) {
            vector<long long> nv(size, 0);
            for (int j = 0; j < size; j++) {
                long long s = 0;
                for (int i = 0; i < size; i++) s = (s + vec[i] * mat[i][j]) % MOD;
                nv[j] = s;
            }
            vec = nv;
        }
        L >>= 1;
        if (L > 0) {
            vector<vector<long long>> sq(size, vector<long long>(size, 0));
            for (int i = 0; i < size; i++)
                for (int k = 0; k < size; k++) {
                    if (mat[i][k] == 0) continue;
                    for (int j = 0; j < size; j++) sq[i][j] = (sq[i][j] + mat[i][k] * mat[k][j]) % MOD;
                }
            mat = sq;
        }
    }
    cout << vec[3 * (n - 1)] % MOD << "\n";

    return 0;
}

