import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long L = Long.parseLong(next());
        long[][] roads = new long[(int) m][3];
        for (int i = 0; i < roads.length; i++) {
            for (int j = 0; j < roads[i].length; j++) {
                roads[i][j] = Long.parseLong(next());
            }
        }

        long MOD = 1000000007L;
        int cn = (int) n;
        int size = 3 * cn;
        long[][] mat = new long[size][size];
        for (int v = 0; v < cn; v++) {
            mat[3 * v + 1][3 * v] += 1;
            mat[3 * v + 2][3 * v + 1] += 1;
        }
        for (int k = 0; k < m; k++) mat[3 * ((int) roads[k][0] - 1)][3 * ((int) roads[k][1] - 1) + (int) roads[k][2] - 1] += 1;
        long[] vec = new long[size];
        vec[0] = 1;
        while (L > 0) {
            if ((L & 1) == 1) {
                long[] nv = new long[size];
                for (int j = 0; j < size; j++) {
                    long s = 0;
                    for (int i = 0; i < size; i++) s = (s + vec[i] * mat[i][j]) % MOD;
                    nv[j] = s;
                }
                vec = nv;
            }
            L >>= 1;
            if (L > 0) {
                long[][] sq = new long[size][size];
                for (int i = 0; i < size; i++) {
                    for (int k = 0; k < size; k++) {
                        if (mat[i][k] == 0) continue;
                        for (int j = 0; j < size; j++) sq[i][j] = (sq[i][j] + mat[i][k] * mat[k][j]) % MOD;
                    }
                }
                mat = sq;
            }
        }
        System.out.println(vec[3 * (cn - 1)] % MOD);
    }
}
